import {vitamins,vitaminById,sources,interactions,REVIEWED,VERSION} from './data.js';
import {normalize,parseNumber,referenceFor,validateProfile,manualEntry,foodEntry,assess,safeSnapshot} from './engine.js';

const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',book:'M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v15h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3z M12 6v15',calculator:'M5 3h14v18H5z M8 7h8 M8 11h1 M15 11h1 M8 15h1 M15 15h1 M8 18h1 M15 18h1',compare:'M7 3v18 M17 3v18 M3 7l4-4 4 4 M13 17l4 4 4-4',shield:'M12 3l8 3v6c0 4-4 7-8 9-4-2-8-5-8-9V6z M8 12l3 3 5-6',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',briefcase:'M8 6V3h8v3 M3 6h18v15H3z M3 11a25 25 0 0 0 18 0 M10 12h4',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-2a8 8 0 0 1 16 0v2',menu:'M4 6h16 M4 12h16 M4 18h16',arrow:'M19 12H5 M11 6l-6 6 6 6',search:'M15.5 15.5L21 21 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bookmark:'M6 3h12v18l-6-4-6 4z',close:'M6 6l12 12 M6 18L18 6',plus:'M12 5v14 M5 12h14',trash:'M4 6h16 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',print:'M7 8V3h10v5 M7 17H3V9h18v8h-4 M7 14h10v7H7z',leaf:'M20 3C4 3 2 10 6 16s14 3 14-13z M4 21L16 8',check:'M5 12l4 4L19 6',upload:'M12 16V3 M7 8l5-5 5 5 M4 16v5h16v-5',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',external:'M14 3h7v7 M21 3L10 14 M10 3H3v18h18v-7',cap:'M2 9l10-5 10 5-10 5z M6 11v5c0 2 3 3 6 3s6-1 6-3v-5 M22 9v6',cpu:'M7 7h10v10H7z M10 10h4v4h-4z M9 3v4 M15 3v4 M9 17v4 M15 17v4 M3 9h4 M3 15h4 M17 9h4 M17 15h4',target:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M18 12a6 6 0 1 1-12 0 6 6 0 0 1 12 0 M13 12a1 1 0 1 1-2 0 1 1 0 0 1 2 0',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',heart:'M12 20s-8-5-8-11a4.5 4.5 0 0 1 8-3 4.5 4.5 0 0 1 8 3c0 6-8 11-8 11z',pin:'M12 21s-7-6-7-12a7 7 0 0 1 14 0c0 6-7 12-7 12z M14.5 9a2.5 2.5 0 1 1-5 0 2.5 2.5 0 0 1 5 0'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('fa-IR',{maximumFractionDigits:2}), unit=u=>`<span class="ltr">${esc(u)}</span>`;
const shortDate=new Date(REVIEWED+'T12:00:00Z').toLocaleDateString('fa-IR',{year:'numeric',month:'long',day:'numeric'});
const storageKey='vitara-v1';
const state={profile:{age:30,sex:'female',stage:'ordinary',smoker:false},entries:[],favorites:[],persist:false,filter:'all',query:'',selected:'D',compare:['D','B12','C'],entryTab:'food',drugs:[],risk:[]};
try{const raw=localStorage.getItem(storageKey);if(raw){const data=JSON.parse(raw);const clean=safeSnapshot(data);state.profile=clean.profile;state.entries=clean.entries;state.favorites=Array.isArray(data.favorites)?data.favorites.filter(id=>vitaminById[id]):[];state.persist=true;}}catch{ /* Unavailable or invalid storage never prevents using the app. */ }
function snapshot(){return {version:1,appVersion:VERSION,exported:new Date().toISOString(),profile:state.profile,entries:state.entries,favorites:state.favorites};}
function save(){if(!state.persist)return;try{localStorage.setItem(storageKey,JSON.stringify(snapshot()));}catch{state.persist=false;toast('ذخیره مرورگر در دسترس نیست؛ برای نگهداری، فایل پشتیبان بگیرید.');}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
const badge=v=>`<span class="vitamin-badge" style="--accent:${v.color}">${v.id}</span>`;
const title=(head,desc,eyebrow='دانش ویتامین، برای انتخاب آگاهانه')=>`<div class="page-title"><div><span class="eyebrow">${eyebrow}</span><h1>${head}</h1><p>${desc}</p></div><span class="date-chip">${icon('leaf',13)} مرور منابع · ${shortDate}</span></div>`;
const sourceLink=(v,label='مشاهده منبع علمی')=>`<a href="${v.source}" target="_blank" rel="noopener noreferrer">${label} ${icon('external',12)}</a>`;
const empty=(text,sub='')=>`<div class="empty">${icon('leaf',25)}${text}${sub?`<p>${sub}</p>`:''}</div>`;
function card(v){return `<article class="vitamin-card" style="--accent:${v.color}"><div class="vitamin-top"><a href="#vitamin/${v.id}" aria-label="پرونده ویتامین ${v.id}">${badge(v)}</a><button class="bookmark ${state.favorites.includes(v.id)?'saved':''}" data-action="favorite" data-id="${v.id}" aria-pressed="${state.favorites.includes(v.id)}" aria-label="نشان‌کردن ویتامین ${v.id}">${icon('bookmark',16)}</button></div><a href="#vitamin/${v.id}"><h3>ویتامین <span class="ltr">${v.id}</span></h3><div class="en">${v.en}</div><p>${v.role}</p><div class="card-bottom"><span><i class="solubility-dot"></i>محلول در ${v.solubility==='fat'?'چربی':'آب'}</span>${icon('arrow',14)}</div></a></article>`;}
const botanic=`<svg class="botanical" viewBox="0 0 240 240" aria-hidden="true"><defs><linearGradient id="leafGrad" x2="1" y2="1"><stop stop-color="#668054"/><stop offset="1" stop-color="#a5b58b"/></linearGradient><linearGradient id="orangeGrad" x2=".9" y2="1"><stop stop-color="#e5b773"/><stop offset="1" stop-color="#d3934a"/></linearGradient></defs><circle cx="120" cy="120" r="102" fill="#e4e9d8"/><path d="M55 170Q105 95 160 44" stroke="#6c8257" stroke-width="2" fill="none"/><path d="M82 130Q40 85 67 49Q100 57 98 106Z" fill="url(#leafGrad)"/><path d="M105 102Q107 53 149 42Q162 77 105 102" fill="#8fa57b"/><path d="M112 101Q160 67 182 94Q176 132 112 119" fill="#718c5c"/><path d="M87 139Q57 123 46 90Q22 131 76 158" fill="#a4b48b"/><circle cx="150" cy="158" r="46" fill="url(#orangeGrad)"/><circle cx="150" cy="158" r="38" fill="#f4d39e"/><circle cx="150" cy="158" r="32" fill="#eab86d"/><g stroke="#f8dfb3" stroke-width="2"><path d="M150 126v64M118 158h64M127 135l46 46M127 181l46-46"/></g><circle cx="150" cy="158" r="4" fill="#f7e7c9"/><ellipse cx="88" cy="179" rx="16" ry="24" transform="rotate(-38 88 179)" fill="#c0a07a"/><path d="M76 161l24 34" stroke="#9c7b55" fill="none"/><ellipse cx="60" cy="170" rx="12" ry="19" transform="rotate(16 60 170)" fill="#d3b48c"/><path d="M65 152l-11 35" stroke="#b39369"/><path d="M169 106q6-16 21-14q1 18-21 14" fill="#8c9f67"/></svg>`;
function home(){return `${title('آگاهی بیشتر، انتخاب بهتر','دنیای ویتامین‌ها را بشناسید؛ نیاز بدن خود را آگاهانه دنبال کنید.','به ویتارا خوش آمدید')}<section class="hero"><div class="hero-copy"><div class="hero-kicker"><span></span>علم تغذیه، به زبان زندگی</div><h1>بدن شما،<br>داستانی از <em>ویتامین‌ها</em></h1><p>از شناخت منابع غذایی تا بررسی دریافت روزانه؛ با تکیه بر منابع معتبر، قدم بعدی سلامت خود را آگاهانه بردارید.</p><div class="hero-actions"><a class="btn" href="#calculator">دریافت روزانه من ${icon('arrow',16)}</a><a class="btn ghost" href="#vitamins">کشف ویتامین‌ها ${icon('book',16)}</a></div></div><div class="hero-art"><div class="orbit">${botanic}<span class="v-orbit o1">D</span><span class="v-orbit o2">K</span><span class="v-orbit o3">C</span><span class="v-orbit o4">B₁₂</span></div><span class="art-note">یک بشقاب متنوع، یک شروع خوب</span><span class="art-spark">✧</span></div></section><div class="stats-strip"><div class="stat"><span class="stat-icon">${icon('book',20)}</span><div><strong>۱۳ ویتامین</strong><small>پرونده‌های علمی ساختاریافته</small></div></div><div class="stat"><span class="stat-icon">${icon('leaf',20)}</span><div><strong>۳۹ نمونه غذایی</strong><small>با مقدار و سهم مشخص</small></div></div><div class="stat"><span class="stat-icon">${icon('shield',20)}</span><div><strong class="ltr">NIH / ODS</strong><small>مرجع اصلی محاسبات</small></div></div></div><div class="section-heading"><div><h2>از کجا شروع کنیم؟</h2><p>ابزارهایی ساده، برای تصمیم‌هایی آگاهانه‌تر</p></div></div><div class="home-tools"><a class="tool-card" href="#calculator"><span class="tool-icon">${icon('calculator',21)}</span><h3>دریافت روزانه من چقدر است؟</h3><p>غذا و مکمل را ثبت و با مقدار مرجع مقایسه کنید.</p><span>شروع محاسبه ${icon('arrow',15)}</span></a><a class="tool-card" href="#compare"><span class="tool-icon">${icon('compare',21)}</span><h3>ویتامین‌ها چه تفاوتی دارند؟</h3><p>نقش، منابع و نکات ایمنی را کنار هم ببینید.</p><span>مقایسه ویتامین‌ها ${icon('arrow',15)}</span></a><a class="tool-card" href="#safety"><span class="tool-icon">${icon('shield',21)}</span><h3>مکمل من با دارو تداخل دارد؟</h3><p>تداخلات منتخب و احتیاط‌های مهم را مرور کنید.</p><span>بررسی ایمنی ${icon('arrow',15)}</span></a></div><div class="section-heading"><div><h2>دنیای ویتامین‌ها</h2><p>هر ویتامین، نقشی کوچک و اثری مهم</p></div><a class="text-link" href="#vitamins">مشاهده هر ۱۳ ویتامین ${icon('arrow',14)}</a></div><div class="vitamin-grid">${['D','C','B12','A'].map(id=>card(vitaminById[id])).join('')}</div><div class="home-bottom"><div class="editorial-note">${icon('shield',24)}<div><h3>دانستن منبع، بخشی از آگاهی است.</h3><p>پشت هر مقدار مرجع، پیوند منبع علمی قرار دارد. دریافت کمتر از مرجع در یک روز، به معنای تشخیص کمبود نیست.</p><a class="text-link section-gap" href="#evidence">با روش علمی ویتارا آشنا شوید ←</a></div></div><div class="daily-note"><span>“</span><span class="eyebrow">یادداشت تغذیه</span><h3>بیشتر، همیشه بهتر نیست.</h3><p>مکمل را با نیاز واقعی و شرایط خود بسنجید؛ مقدار مرجع غذایی با مقدار مصرف درمانی تفاوت دارد.</p></div></div>`;}
function vitaminList(){return `${title('دانشنامه ویتامین‌ها','۱۳ ویتامین ضروری؛ از عملکرد در بدن تا منابع غذایی و ایمنی.')}<div class="knowledge-toolbar"><div class="search-field">${icon('search',16)}<input id="vitaminSearch" value="${esc(state.query)}" placeholder="نام ویتامین، نقش یا منبع غذایی..." aria-label="جست‌وجوی ویتامین"></div><div class="filter-tabs" role="group" aria-label="فیلتر ویتامین‌ها">${[['all','همه'],['fat','محلول در چربی'],['water','محلول در آب'],['B','گروه B'],['saved','نشان‌شده‌ها']].map(([id,label])=>`<button data-action="filter" data-id="${id}" class="${state.filter===id?'active':''}" aria-pressed="${state.filter===id}">${label}</button>`).join('')}</div></div><div id="vitaminResults"></div>`;}
function updateVitaminResults(){const q=normalize(state.query);const list=vitamins.filter(v=>(state.filter==='all'||v.solubility===state.filter||state.filter==='B'&&v.id.startsWith('B')||state.filter==='saved'&&state.favorites.includes(v.id))&&normalize([v.id,v.name,v.en,v.role,...v.foods.map(f=>f.name)].join(' ')).includes(q));$('#vitaminResults').innerHTML=`<div class="result-count" role="status">${fmt(list.length)} پرونده علمی</div>${list.length?`<div class="vitamin-grid">${list.map(card).join('')}</div>`:empty('نتیجه‌ای پیدا نشد.','نام دیگری جست‌وجو کنید یا فیلتر را تغییر دهید.')}`;}
function vitaminDetail(id){const v=vitaminById[id];if(!v)return notFound();const ref=referenceFor(id,state.profile);return `<a href="#vitamins" class="text-link" style="margin-bottom:22px">→ بازگشت به دانشنامه</a><div class="detail-head">${badge(v)}<div><span class="eyebrow">${v.name}</span><h1>ویتامین <span class="ltr">${id}</span></h1><p class="ltr">${v.en}</p></div></div><div class="detail-meta"><span class="pill">محلول در ${v.solubility==='fat'?'چربی':'آب'}</span><span class="pill">${v.type} · مرجع آمریکا</span><span class="pill">مرور منبع · ${shortDate}</span></div><div class="notice info">این پرونده آموزشی است. مقدار مرجع برای جمعیت سالم است؛ نیاز بالینی فرد می‌تواند متفاوت باشد. محتوای این نسخه هنوز تأیید مستقل یک متخصص بالینی را دریافت نکرده است.</div><div class="detail-grid"><div class="panel">${[['شناخت و عملکرد',v.definition],['جذب و متابولیسم',v.metabolism],['کمبود و عوامل خطر',v.risk],['دریافت بیش از حد و ایمنی',v.safety],['ارزیابی آزمایشگاهی',v.lab],['شکل‌های مکمل و واحدها',v.forms]].map(([h,t])=>`<section class="detail-section"><h3>${h}</h3><p>${t}</p></section>`).join('')}</div><div class="stack"><div class="panel"><h2>مقدار مرجع شما</h2><p>بر اساس <button class="btn ghost small" data-action="profile">مشخصات انتخاب‌شده ${icon('user',13)}</button></p><div style="font-size:30px;color:var(--green);margin:15px 0">${fmt(ref.amount)} ${unit(v.unit)} <span class="value-unit">در روز</span></div><div class="result-fact"><span>نوع مرجع</span><b>${v.type}</b></div><div class="result-fact"><span>حد بالای آمریکا (UL)</span><b>${v.ul===null?'تعیین نشده':fmt(v.ul)+' '+unit(id==='B9'?'mcg folic acid':v.unit)}</b></div><p class="footer-note">${scopeText(v)}</p><div class="form-actions"><a href="#calculator/${id}" class="btn small">محاسبه دریافت ${icon('arrow',14)}</a></div></div><div class="panel"><h2>مقادیر مرجع بزرگسالان</h2><div class="table-wrap"><table><thead><tr><th>گروه</th><th>${v.type} در روز</th></tr></thead><tbody>${[['مردان',0],['زنان',1],['بارداری ۱۹–۵۰ سال',2],['شیردهی ۱۹–۵۰ سال',3]].map(([name,i])=>`<tr><td>${name}</td><td>${fmt(v.reference[i])} ${unit(v.unit)}</td></tr>`).join('')}</tbody></table></div><p class="footer-note">پایه ۱۹–۵۰ سال. ${id==='D'?'بیش از ۷۰ سال: ۲۰ میکروگرم.':id==='B6'?'پس از ۵۰ سال: مردان ۱٫۷، زنان ۱٫۵ mg.':id==='C'?'افراد سیگاری: ۳۵ mg بیشتر.':'برای سایر سنین بزرگسالی، مرجع پایه ثابت است.'}</p></div></div></div><section class="section-gap"><div class="section-heading"><div><h2>از بشقاب غذا تا بدن شما</h2><p>نمونه‌های جدول غذایی NIH؛ مقدار به نوع و روش آماده‌سازی وابسته است.</p></div></div><div class="table-wrap"><table><thead><tr><th>غذا</th><th>یک سهم مرجع</th><th>مقدار ویتامین</th><th>منبع</th></tr></thead><tbody>${v.foods.map(f=>`<tr><td>${f.name}</td><td>${f.serving}</td><td>${fmt(f.amount)} ${unit(v.unit)}</td><td>${sourceLink(v,'NIH ODS ↗')}</td></tr>`).join('')}</tbody></table></div></section><div class="panel section-gap"><h2>شواهد و حدود تفسیر</h2><p>نقش فیزیولوژیک و مقادیر مرجع، مبنای این صفحه‌اند. از آن‌ها نمی‌توان نتیجه گرفت که مکمل در فرد بدون کمبود، بیماری را پیشگیری یا درمان می‌کند. شدت علائم یا درصد دریافت، سطح قطعیت یک تشخیص نیست.</p><div class="form-actions">${sourceLink(v)}<a class="btn secondary small" href="#evidence">روش انتخاب منابع</a></div></div>`;}
function scopeText(v){return {total:'UL شامل غذا و مکمل است؛ زیر این حد بودن، ایمنی فردی را تضمین نمی‌کند.',preformed:'UL فقط برای رتینول و ویتامین A پیش‌ساخته است؛ کاروتنوئید غذایی در آن جمع نمی‌شود.',added:v.id==='E'?'UL مربوط به آلفا توکوفرول مکملی است. مقادیر افزوده را جدا ثبت کنید.':'UL فقط برای نیاسین افزوده از مکمل و غذای غنی‌شده است.',folic:'UL بر حسب اسیدفولیک افزوده است، نه فولات طبیعی غذا و نه DFE.',none:'حد بالا تعیین نشده است؛ نبود UL به معنی بی‌خطر بودن دریافت نامحدود نیست.'}[v.ulScope];}
function profileFields(prefix='p'){const p=state.profile;return `<div class="field-grid"><div class="field"><label for="${prefix}Age">سن (سال)</label><input id="${prefix}Age" name="age" inputmode="numeric" value="${p.age}" required aria-describedby="${prefix}AgeNote"><small id="${prefix}AgeNote">دامنه این نسخه: ۱۹ تا ۱۲۰ سال</small></div><div class="field"><label for="${prefix}Sex">گروه مرجع فیزیولوژیک</label><select id="${prefix}Sex" name="sex"><option value="female" ${p.sex==='female'?'selected':''}>زنان</option><option value="male" ${p.sex==='male'?'selected':''}>مردان</option></select></div><div class="field"><label for="${prefix}Stage">وضعیت فیزیولوژیک</label><select id="${prefix}Stage" name="stage"><option value="ordinary" ${p.stage==='ordinary'?'selected':''}>وضعیت معمول</option><option value="pregnancy" ${p.stage==='pregnancy'?'selected':''}>بارداری (۱۹–۵۰ سال)</option><option value="lactation" ${p.stage==='lactation'?'selected':''}>شیردهی (۱۹–۵۰ سال)</option></select></div><div class="field"><label for="${prefix}Standard">استاندارد محاسبه</label><select id="${prefix}Standard"><option>آمریکا · NIH / DRI</option></select><small>تفاوت منتخب اروپا در B6 نمایش داده می‌شود.</small></div></div><label class="check-label"><input type="checkbox" name="smoker" ${p.smoker?'checked':''}>مصرف سیگار (فقط مرجع ویتامین C را تغییر می‌دهد)</label>`;}
function calculator(){const v=vitaminById[state.selected];return `${title('دریافت روزانه من','مقدار ثبت‌شده غذا و مکمل را با مرجع غذایی بزرگسالان مقایسه کنید.')}<div class="calculator-layout"><div class="stack"><section class="panel"><h2>۱. مشخصات مرجع شما</h2><form id="profileForm">${profileFields('calc')}<div class="form-actions"><button class="btn small" type="submit">اعمال مشخصات ${icon('check',15)}</button><span class="muted" style="font-size:10px">وزن، مبنای تغییر خودکار نیاز ویتامین نیست.</span></div><div class="error-text" id="profileError" role="alert"></div></form></section><section class="panel"><h2>۲. انتخاب ویتامین</h2><div class="field"><label for="vitaminSelect">کدام ویتامین را بررسی کنیم؟</label><select id="vitaminSelect">${vitamins.map(x=>`<option value="${x.id}" ${x.id===v.id?'selected':''}>ویتامین ${x.id} · ${x.name}</option>`).join('')}</select></div><div class="section-gap" id="entryFormContainer">${entryForm()}</div></section><section class="panel"><div class="section-heading"><h2 style="margin:0">۳. دریافت‌های ثبت‌شده <span class="ltr">${v.id}</span></h2><button class="btn ghost small" data-action="clearVitamin">پاک‌کردن</button></div><div class="notice info">فقط دریافت همین ویتامین ثبت می‌شود؛ این فهرست، محاسبه کامل تمام مواد مغذی یک وعده نیست.</div><div id="entryList" class="entry-list"></div></section></div><div id="calculatorResult"></div></div>`;}
function entryForm(){const v=vitaminById[state.selected],food=state.entryTab==='food';return `<div class="entry-tabs" role="group" aria-label="نوع ثبت دریافت"><button data-action="entryTab" data-id="food" class="${food?'active':''}">${icon('leaf',15)} از غذاهای مرجع</button><button data-action="entryTab" data-id="manual" class="${!food?'active':''}">${icon('plus',15)} مکمل / ورود دستی</button></div>${food?`<form id="foodForm"><div class="field"><label for="foodSelect">غذا و سهم مرجع</label><select id="foodSelect" name="food">${v.foods.map(f=>`<option value="${f.id}">${f.name} · ${f.serving} · ${fmt(f.amount)} ${v.unit}</option>`).join('')}</select></div><div class="field section-gap"><label for="servings">تعداد سهم مصرف‌شده</label><input id="servings" name="servings" value="1" inputmode="decimal" required><small>مثلاً ۰٫۵ یعنی نصفِ سهم مشخص‌شده بالا.</small></div><div class="form-actions"><button class="btn small" type="submit">افزودن غذا ${icon('plus',15)}</button>${sourceLink(v,'منبع مقدار غذایی ↗')}</div><div class="error-text" id="entryError" role="alert"></div></form>`:`<form id="manualForm"><div class="field-grid"><div class="field"><label for="entryLabel">نام غذا یا مکمل</label><input id="entryLabel" name="label" maxlength="100" required placeholder="مثلاً مکمل مصرف‌شده امروز"></div><div class="field"><label for="entryKind">نوع منبع</label><select id="entryKind" name="kind"><option value="supplement">مکمل</option><option value="food">غذای طبیعی</option><option value="fortified">بخش افزوده غذای غنی‌شده</option></select></div><div class="field"><label for="manualAmount" id="amountLabel">${v.id==='B9'?'مقدار اسیدفولیک (mcg، همراه غذا)':'مقدار مصرف‌شده امروز'}</label><input id="manualAmount" name="amount" inputmode="decimal" required placeholder="۰"><small>مقدار دریافت واقعی، نه مقدار هر قرص بدون محاسبه تعداد.</small></div><div class="field"><label for="manualUnit">واحد</label><select id="manualUnit" name="unit"><option value="${v.id==='B9'?'mcg folic acid':v.unit}">${v.id==='B9'?'mcg اسیدفولیک (تبدیل به DFE)':v.unit}</option>${v.id==='D'?'<option value="IU">IU</option>':''}</select></div></div>${v.id==='A'?`<div class="field section-gap"><label for="entryForm">شکل ویتامین A</label><select id="entryForm" name="form"><option value="unknown">نامشخص / ترکیبی</option><option value="preformed">پیش‌ساخته (رتینول / رتینیل‌استر)</option><option value="carotenoid">فقط کاروتنوئید (مقدار تبدیل‌شده به RAE)</option></select><small>بدون تفکیک شکل، ارزیابی کامل UL ممکن نیست.</small></div>`:v.id==='B9'?'<input type="hidden" name="form" value="folicWithFood"><div class="notice section-gap" id="folateNote">برای مکمل، فقط اسیدفولیک مصرف‌شده همراه غذا پشتیبانی می‌شود. عدد mcg اسیدفولیک را وارد کنید؛ DFE یا متیل‌فولات را در این حالت وارد نکنید.</div>':''}<div class="form-actions"><button class="btn small" type="submit">ثبت دریافت ${icon('plus',15)}</button></div><div class="error-text" id="entryError" role="alert"></div></form>`}`;}
function updateCalc(){const v=vitaminById[state.selected],r=assess(v.id,state.profile,state.entries),entries=state.entries.filter(e=>e.vitamin===v.id);$('#entryList').innerHTML=entries.length?entries.map(e=>`<div class="entry-row"><span class="stat-icon">${icon(e.kind==='food'?'leaf':'plus',17)}</span><div class="entry-meta"><strong>${esc(e.label)}</strong><small>${e.servings?fmt(e.servings)+' سهم · ':''}${{food:'غذا',supplement:'مکمل',fortified:'بخش افزوده غذای غنی‌شده'}[e.kind]}${e.serving?' · '+esc(e.serving):''}</small></div><span class="entry-value">${fmt(e.amount)} ${unit(v.unit)}</span><button class="icon-btn" data-action="removeEntry" data-id="${esc(e.id)}" aria-label="حذف ${esc(e.label)}">${icon('trash',14)}</button></div>`).join(''):empty('هنوز دریافتی ثبت نشده است.','غذا یا مکمل مصرف‌شده امروز را اضافه کنید.');const status={empty:'منتظر ثبت دریافت',below:'مقدار ثبت‌شده کمتر از مرجع',reference:'مقدار ثبت‌شده در حد مرجع یا بیشتر',over:'دریافت ثبت‌شده از UL آمریکا بیشتر است'}[r.level];$('#calculatorResult').innerHTML=`<section class="panel result-panel"><div style="display:flex;justify-content:space-between;align-items:center"><h2 style="margin:0">نگاه امروز شما</h2><span class="pill ltr">${v.id} · ${v.type}</span></div><p style="font-size:10px;margin-top:7px">${v.name} · ${fmt(state.profile.age)} سال</p><div class="result-ring" style="--progress:${Math.min(100,r.percent)}%"><div class="ring-text"><strong>${r.entries?fmt(r.percent)+'٪':'—'}</strong><small>از مقدار مرجع روزانه</small></div></div><div class="result-status">${status}</div><div class="result-facts"><div class="result-fact"><span>مجموع ثبت‌شده</span><b>${r.entries?fmt(r.total)+' '+unit(v.unit):'هنوز ثبت نشده'}</b></div><div class="result-fact"><span>مرجع ${r.ref.type}</span><b>${fmt(r.ref.amount)} ${unit(v.unit)}</b></div><div class="result-fact"><span>حد بالای آمریکا</span><b>${v.ul===null?'تعیین نشده':fmt(v.ul)+' '+unit(v.id==='B9'?'mcg folic acid':v.unit)}</b></div>${v.ul!==null?`<div class="result-fact"><span>دریافت قابل مقایسه با UL</span><b>${fmt(r.ulTotal)} ${unit(v.id==='B9'?'mcg folic acid':v.unit)}</b></div>`:''}</div>${r.over?'<div class="notice error">مقدار ثبت‌شده از حد بالا بیشتر است. برچسب‌ها و تکرار مکمل‌ها را با پزشک یا داروساز بررسی کنید؛ این سامانه دوز درمانی تعیین نمی‌کند.</div>':''}${r.incompleteUL?'<div class="notice">شکل بخشی از ویتامین A مشخص نیست؛ UL به‌طور کامل قابل ارزیابی نیست.</div>':''}${r.efsaB6?'<div class="notice">این دریافت از حد بالای EFSA (۱۲ mg در روز، ۲۰۲۳) بیشتر است؛ حتی اگر از UL آمریکا کمتر باشد.</div>':''}<p class="note-small">${scopeText(v)}</p><p class="note-small">ثبت یک روز و مقایسه با ${v.type}، تشخیص کمبود یا تضمین کفایت نیست. ${v.type==='AI'?'کمتر بودن از AI به‌تنهایی نشان‌دهنده ناکافی بودن دریافت نیست.':''}${v.id==='B3'?'سهم تبدیل تریپتوفان به نیاسین در محاسبه غذا لحاظ نشده است.':''}</p><div class="form-actions">${sourceLink(v,'مرجع محاسبه ↗')}<a href="#workspace">گزارش کامل ←</a></div></section><div class="notice section-gap">مقادیر غذایی نمونه‌اند و با رقم گیاهی، برند و پخت تفاوت دارند. اطلاعات برچسب باید با واحد صحیح وارد شود.</div>`;}
function compare(){const list=state.compare.map(id=>vitaminById[id]);return `${title('مقایسه ویتامین‌ها','دو تا چهار ویتامین را انتخاب کنید و تفاوت‌ها را کنار هم ببینید.')}<div class="compare-select" role="group" aria-label="انتخاب ویتامین برای مقایسه">${vitamins.map(v=>`<label class="compare-option"><input type="checkbox" data-compare="${v.id}" ${state.compare.includes(v.id)?'checked':''}><span class="ltr">${v.id}</span></label>`).join('')}</div><div class="table-wrap"><table class="comparison"><thead><tr><th>ویژگی</th>${list.map(v=>`<th>${badge(v)}<div>ویتامین ${v.id}</div></th>`).join('')}</tr></thead><tbody>${[['نام',v=>v.name],['دسته',v=>'محلول در '+(v.solubility==='fat'?'چربی':'آب')],['نقش اصلی',v=>v.role],['مرجع مشخصات شما',v=>fmt(referenceFor(v.id,state.profile).amount)+' '+unit(v.unit)+' · '+v.type],['حد بالای آمریکا',v=>v.ul===null?'تعیین نشده':fmt(v.ul)+' '+unit(v.id==='B9'?'mcg folic acid':v.unit)],['دامنه حد بالا',scopeText],['نمونه منابع غذایی',v=>v.foods.map(f=>f.name).join('، ')],['احتیاط مهم',v=>v.safety],['منبع',v=>sourceLink(v,'NIH ODS ↗')]].map(([h,get])=>`<tr><td>${h}</td>${list.map(v=>`<td>${get(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="form-actions"><button class="btn secondary small" data-action="profile">${icon('user',15)} تغییر مشخصات مرجع</button></div><div class="notice section-gap">مرجع فعلی آمریکا است. تفاوت منتخب B6: حد بالای EFSA برابر ۱۲ mg در روز است. حد بالا هدف مصرف نیست.</div>`;}
function safety(){return `${title('ایمنی، پیش از مصرف','مرور تداخلات منتخب و عوامل خطر؛ برای گفت‌وگویی آگاهانه با تیم درمان.')}<div class="notice">این بررسی، فهرست جامع تداخلات یا ابزار تشخیص نیست. نبود نتیجه برای یک دارو به معنای بی‌خطر بودن ترکیب نیست.</div><div class="two-col section-gap"><section class="panel"><h2>داروهای مصرفی را انتخاب کنید</h2><div class="interactions-list">${interactions.map(x=>`<label class="interaction-row"><input type="checkbox" data-drug="${x.id}" ${state.drugs.includes(x.id)?'checked':''}><span>${x.name}<small>مرتبط با ویتامین ${x.vitamins.join('، ')}</small></span></label>`).join('')}</div></section><div class="stack"><section class="panel"><h2>نکات مرتبط با انتخاب شما</h2><div id="interactionResults"></div></section><section class="panel"><h2>چه چیزی نیازمند توجه بیشتر است؟</h2><p>انتخاب این موارد فقط نکات آموزشی مرتبط را نشان می‌دهد و امتیاز احتمال کمبود تولید نمی‌کند.</p><div class="risk-list">${[['vegan','رژیم وگان بدون غذای غنی‌شده یا مکمل B12'],['malabsorption','سابقه اختلال جذب یا جراحی گوارشی'],['biotin','مصرف بیوتین و برنامه انجام آزمایش']].map(([id,label])=>`<label class="check-label"><input type="checkbox" data-risk="${id}" ${state.risk.includes(id)?'checked':''}>${label}</label>`).join('')}</div><div id="riskResults"></div></section></div></div>`;}
function safetyResults(){const selected=interactions.filter(x=>state.drugs.includes(x.id));$('#interactionResults').innerHTML=selected.length?selected.map(x=>`<article class="risk-result"><h3>${x.name}</h3><p>${x.text}</p>${x.vitamins.map(id=>sourceLink(vitaminById[id],`منبع ${id} ↗`)).join(' · ')}</article>`).join(''):empty('دارویی انتخاب نشده است.','یک مورد از فهرست را برای مرور نکات مرتبط انتخاب کنید.');const tips={vegan:['B12','غذاهای گیاهی معمول، منبع قابل اتکای B12 نیستند. برنامه تأمین از غذای غنی‌شده یا مکمل باید بررسی شود.'],malabsorption:['D','اختلال جذب می‌تواند دریافت مؤثر چند ویتامین را تغییر دهد. مقادیر جمعیتی به‌تنهایی برای تنظیم درمان کافی نیستند.'],biotin:['B7','بیوتین می‌تواند نتیجه بعضی آزمایش‌ها را مخدوش کند. نام و مقدار مکمل را به پزشک و آزمایشگاه اطلاع دهید؛ زمان قطع برای همه یکسان نیست.']};$('#riskResults').innerHTML=state.risk.map(id=>`<div class="risk-result"><p>${tips[id][1]}</p>${sourceLink(vitaminById[tips[id][0]],'مطالعه منبع ↗')}</div>`).join('');}
function evidence(){return `${title('منبع روشن، انتخاب مطمئن‌تر','مبنای علمی محاسبات، تفاوت استانداردها و محدودیت داده‌ها را بشناسید.')}<div class="notice info">تاریخ دسترسی و مرور منابع: ${shortDate}. این تاریخ، تاریخ انتشار یا آخرین به‌روزرسانی همه منابع نیست. مرور منابع با تأیید مستقل بالینی تفاوت دارد.</div><div class="glossary">${[['RDA','مقدار توصیه‌شده برای تقریباً همه افراد سالم یک گروه؛ نسخه درمانی نیست.'],['AI','دریافت کافی؛ زمانی استفاده می‌شود که داده برای RDA کافی نیست.'],['EAR','نیاز متوسط برآوردشده؛ عمدتاً برای تحلیل دریافت معمول گروه‌ها به کار می‌رود.'],['UL','حد بالای دریافت معمول با احتمال کم عارضه؛ هدف مصرف یا مرز قطعی ایمنی نیست.']].map(([h,p])=>`<div><h3>${h}</h3><p>${p}</p></div>`).join('')}</div><div class="source-grid section-gap">${sources.map(s=>`<article class="source-card"><span class="pill">${s.tag}</span><h3 class="ltr">${s.name}</h3><p>${s.text}</p><a href="${s.url}" target="_blank" rel="noopener noreferrer">مطالعه منبع اصلی ${icon('external',14)}</a></article>`).join('')}</div><div class="two-col section-gap"><section class="panel"><h2>محاسبه چگونه انجام می‌شود؟</h2><div class="article-steps"><div><strong>۱. انتخاب مرجع جمعیتی</strong>سن، گروه فیزیولوژیک، بارداری یا شیردهی؛ سیگار فقط برای C.</div><div><strong>۲. همسان‌سازی واحدها</strong>جمع دریافت همان ویتامین، با تبدیل مشخص IU برای D و اسیدفولیک همراه غذا به DFE.</div><div><strong>۳. مقایسه همراه با محدودیت</strong>درصد دریافت نسبت به RDA یا AI و بررسی UL فقط برای شکل‌ها و منابع مربوط.</div></div></section><section class="panel"><h2>چه چیزهایی از این ابزار نتیجه نمی‌شود؟</h2><p>ثبت یک روز، برای تشخیص کمبود یا برآورد دریافت معمول کافی نیست. علائم غیراختصاصی، وجود بیماری را اثبات نمی‌کنند. موتور این نسخه برای افراد سالم ۱۹ سال به بالا ساخته شده و دوز درمانی، تفسیر خودکار آزمایش، EAR فردی یا جدول کامل EFSA ارائه نمی‌کند.</p><p class="section-gap">محاسبات با جدول‌ها و قواعد ثابت انجام می‌شوند. دستیار هوش مصنوعی، تشخیص‌گر و تأیید ادعاهای تجاری در این نسخه فعال نیست.</p><a class="text-link section-gap" href="#safety">مرور نکات ایمنی ←</a></section></div>`;}
function statusText(r){return {empty:'فاقد داده',below:'ثبت‌شده کمتر از مرجع',reference:'ثبت‌شده در حد مرجع یا بیشتر',over:'بالاتر از UL آمریکا'}[r.level];}
function workspace(){const results=vitamins.map(v=>({v,r:assess(v.id,state.profile,state.entries)}));const active=results.filter(x=>x.r.entries);return `${title('فضای کار و گزارش دریافت','مرور همه ویتامین‌ها، تهیه گزارش و مدیریت داده‌های همین مرورگر.')}<div class="print-only"><p>گزارش آموزشی ویتارا · ${new Date().toLocaleDateString('fa-IR')} · نسخه ${VERSION}</p></div><div class="workspace-toolbar"><button class="btn" data-action="print">${icon('print',16)} چاپ / ذخیره PDF</button><button class="btn secondary" data-action="export">${icon('download',16)} پشتیبان JSON</button><button class="btn secondary" data-action="import">${icon('upload',16)} بازیابی پشتیبان</button><button class="btn secondary" data-action="profile">${icon('user',16)} مشخصات مرجع</button></div><section class="panel workspace-controls"><h2>کنترل اطلاعات با شماست</h2><p>اطلاعات پرونده از این برنامه به سرور ارسال نمی‌شود. ذخیره اختیاری این مرورگر رمزنگاری‌شده نیست؛ برای اطلاعات قابل شناسایی بیماران از آن استفاده نکنید. با خاموش بودن ذخیره، بازخوانی صفحه دریافت‌ها را پاک می‌کند.</p><label class="check-label"><input id="persistToggle" type="checkbox" ${state.persist?'checked':''}>با آگاهی از این محدودیت‌ها، اطلاعات این جلسه در همین مرورگر نگهداری شود.</label><div class="form-actions"><button class="btn danger small" data-action="erase">${icon('trash',14)} پاک‌کردن همه داده‌های برنامه</button></div></section><div class="workspace-summary"><div><strong>${fmt(state.entries.length)}</strong><small>دریافت ثبت‌شده</small></div><div><strong>${fmt(active.length)} از ۱۳</strong><small>ویتامین دارای داده</small></div><div><strong>${fmt(active.filter(x=>x.r.over||x.r.efsaB6).length)}</strong><small>نیازمند مرور حد بالا</small></div></div><div class="notice info">مشخصات مرجع: ${fmt(state.profile.age)} سال · ${state.profile.sex==='female'?'زنان':'مردان'} · ${{ordinary:'معمول',pregnancy:'بارداری',lactation:'شیردهی'}[state.profile.stage]}${state.profile.smoker?' · سیگاری':''} · آمریکا NIH / DRI. داده‌ها ثبت یک روزند؛ گزارش، تأیید کفایت یا تشخیص نیست.</div><div class="table-wrap section-gap"><table><thead><tr><th>ویتامین</th><th>ثبت‌شده</th><th>مرجع روزانه</th><th>نسبت به مرجع</th><th>تفسیر محدود</th><th>منبع</th></tr></thead><tbody>${results.map(({v,r})=>`<tr><td><a href="#vitamin/${v.id}"><span class="ltr">${v.id}</span></a></td><td>${r.entries?fmt(r.total)+' '+unit(v.unit):'—'}</td><td>${fmt(r.ref.amount)} ${unit(v.unit)} · ${v.type}</td><td>${r.entries?fmt(r.percent)+'٪':'—'}</td><td>${statusText(r)}${r.efsaB6?'<br><span style="color:#a16c39">بالاتر از UL اروپا (B6)</span>':''}${r.incompleteUL?'<br>UL ناقص؛ شکل A نامشخص':''}</td><td>${sourceLink(v,'ODS ↗')}</td></tr>`).join('')}</tbody></table></div><p class="report-caption">منابع مرورشده در ${shortDate}. مقادیر غذایی میانگین نمونه‌اند و اطلاعات دستی نیازمند بررسی برچسب است. UL برای برخی شکل‌ها یا منابع خاص اعمال می‌شود. نبود UL یا هشدار به معنی نبود خطر نیست.</p>${state.entries.length?`<section class="section-gap"><div class="section-heading"><h2>جزئیات دریافت‌ها</h2></div><div class="table-wrap"><table><thead><tr><th>ویتامین</th><th>غذا یا مکمل</th><th>مقدار</th><th>منشأ داده</th></tr></thead><tbody>${state.entries.map(e=>`<tr><td>${e.vitamin}</td><td>${esc(e.label)}</td><td>${fmt(e.amount)} ${unit(vitaminById[e.vitamin].unit)}</td><td class="report-source">${e.source?.startsWith('https://ods.od.nih.gov/')?`<a href="${vitaminById[e.vitamin].source}" target="_blank" rel="noopener noreferrer">جدول NIH ODS</a>`:'ورودی کاربر / فایل پشتیبان'}</td></tr>`).join('')}</tbody></table></div></section>`:''}<p class="footer-note">فضای کار این نسخه یک پرونده بالینی چندکاربره نیست؛ برای استفاده سازمانی، احراز هویت، کنترل نقش‌ها و ذخیره امن سروری باید جداگانه پیاده‌سازی شود.</p>`;}
function notFound(){return `${title('این صفحه پیدا نشد','می‌توانید از دانشنامه یا صفحه اصلی ادامه دهید.')}<a href="#home" class="btn">بازگشت به خانه</a>`;}
function about(){const focus=[['leaf','تغذیه اساسی','پایه‌های علمی نیاز بدن به انرژی و مواد مغذی'],['heart','تغذیه بالینی','نقش تغذیه در پیشگیری و مدیریت بیماری‌ها'],['calculator','رژیم‌درمانی','برنامه‌ریزی تغذیه‌ای هدفمند و مبتنی بر شواهد'],['spark','ویتامین‌ها','عملکرد، منابع غذایی و نیاز روزانه بدن'],['shield','مواد معدنی','پیامدهای کمبود یا دریافت بیش از حد'],['target','ریزمغذی‌ها','نقش ریزمغذی‌ها در حفظ سلامت بدن']];const principles=[['book','یادگیری مستمر','گسترش پیوسته دانش در حوزه علوم تغذیه'],['check','منابع علمی معتبر','مطالعه و ارجاع به منابع قابل‌اعتماد'],['shield','پایبندی به شواهد','تکیه بر یافته‌های پژوهشی، نه ادعا']];return `<section class="about-hero"><div class="about-hero-copy"><span class="about-kicker"><i></i>درباره من</span><h1>آریا <em>غلام‌نیا</em></h1><p class="about-role">${icon('cap',17)} دانشجوی علوم تغذیه</p><p class="about-place">${icon('pin',15)} دانشگاه علوم پزشکی زنجان</p><p class="about-lead">علاقه‌مندی من به شناخت عمیق‌تر ارتباط میان <b>تغذیه، سلامت انسان و پیشگیری از بیماری‌ها</b>، مسیر علمی من را به سمت مطالعه، پژوهش و توسعه دانش در حوزه علوم تغذیه هدایت کرده است.</p><div class="about-tags"><span>علوم تغذیه</span><span>تغذیه بالینی</span><span>ریزمغذی‌ها</span><span>هوش مصنوعی در سلامت</span></div><div class="hero-actions"><a class="btn light" href="#vitamins">${icon('book',16)} دانشنامه ویتامین‌ها</a><a class="btn outline-light" href="#evidence">منابع علمی ${icon('arrow',15)}</a></div></div><figure class="about-photo"><div class="about-photo-frame"><img src="assets/aria-gholamnia.jpg" alt="آریا غلام‌نیا، دانشجوی علوم تغذیه" width="900" height="900" loading="lazy" decoding="async"></div><figcaption><span class="ltr">Vitara</span> · بنیان‌گذار</figcaption><span class="about-orbit o1 ltr">A</span><span class="about-orbit o2 ltr">D</span><span class="about-orbit o3 ltr">C</span></figure></section>
<section class="about-block"><div class="section-heading"><div><span class="eyebrow">حوزه‌های مورد علاقه</span><h2>جایی که علم تغذیه برایم زنده می‌شود</h2></div></div><div class="about-focus">${focus.map(([i,t,d],n)=>`<article class="about-focus-card" style="--d:${n*60}ms"><span>${icon(i,22)}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><p class="about-text">باور دارم که شناخت صحیح نیازهای تغذیه‌ای انسان و درک علمی عملکرد مواد مغذی، از پایه‌های مهم <b>ارتقای سلامت، پیشگیری از کمبودهای تغذیه‌ای و بهبود کیفیت زندگی</b> است. به همین دلیل، تلاش می‌کنم دانش خود را درباره عملکرد مواد مغذی، منابع غذایی، نیازهای روزانه بدن و پیامدهای کمبود یا دریافت بیش از حد آن‌ها به‌صورت مستمر گسترش دهم.</p></section>
<section class="about-duo"><article class="about-feature ai"><span class="about-feature-icon">${icon('cpu',26)}</span><span class="eyebrow">تغذیه × فناوری</span><h2>هوش مصنوعی در خدمت سلامت</h2><p>در کنار علاقه‌مندی به علوم تغذیه، به <b>هوش مصنوعی و کاربردهای آن در پژوهش‌های تغذیه‌ای و سلامت</b> نیز توجه ویژه‌ای دارم. معتقدم ترکیب دانش تغذیه با فناوری‌های نوین، تحلیل داده‌ها و ابزارهای هوشمند می‌تواند فرصت‌های ارزشمندی برای دسترسی بهتر به اطلاعات علمی، شناخت دقیق‌تر نیازهای تغذیه‌ای و توسعه رویکردهای نوین در آموزش و پژوهش فراهم کند.</p></article><article class="about-feature"><span class="about-feature-icon">${icon('target',26)}</span><span class="eyebrow">چرا ویتارا؟</span><h2>هدف از راه‌اندازی این وب‌سایت</h2><p>ایجاد فضایی <b>علمی، کاربردی و قابل‌اعتماد</b> برای معرفی ویتامین‌ها و مواد مغذی و ارائه اطلاعات دقیق و قابل‌فهم درباره نقش آن‌ها در بدن. تلاش می‌کنم مفاهیم تخصصی علوم تغذیه را به زبانی روشن و منظم ارائه کنم تا مخاطبان درک بهتری از نیازهای تغذیه‌ای بدن، منابع غذایی و اهمیت انتخاب‌های آگاهانه در سبک زندگی خود به دست آورند.</p></article></section>
<section class="about-block"><div class="section-heading"><div><span class="eyebrow">اصول کار علمی</span><h2>سه اصلی که به آن پایبندم</h2></div></div><div class="about-principles">${principles.map(([i,t,d],n)=>`<div class="about-principle"><b class="ltr">0${n+1}</b><span>${icon(i,20)}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div><p class="about-text">امیدوارم این وب‌سایت در مسیر توسعه دانش تغذیه، ترویج آگاهی عمومی و ایجاد پیوندی مؤثر میان <b>علم، فناوری و سلامت جامعه</b> گامی ارزشمند بردارد.</p></section>
<section class="about-vision"><span class="about-vision-icon">${icon('eye',28)}</span><span class="about-kicker"><i></i>چشم‌انداز من</span><blockquote>بهره‌گیری از دانش روز علوم تغذیه و ظرفیت‌های هوش مصنوعی برای توسعه آموزش علمی، افزایش آگاهی تغذیه‌ای و کمک به <em>تصمیم‌گیری آگاهانه‌تر</em> در زمینه سلامت.</blockquote><cite>— آریا غلام‌نیا</cite></section>`;}
function openDialog(h,content){$('#dialogContent').innerHTML=`<div class="dialog-body"><div class="dialog-header"><h2 id="dialogTitle">${h}</h2><button class="icon-btn" data-action="closeDialog" aria-label="بستن پنجره">${icon('close',16)}</button></div>${content}</div>`;$('#dialog').showModal();}
function profileDialog(){openDialog('مشخصات مرجع شما',`<p>این مشخصات فقط برای انتخاب ردیف مرجع غذایی است؛ اطلاعات تشخیصی محسوب نمی‌شود.</p><form id="dialogProfile">${profileFields('dialog')}<div class="error-text" id="dialogError" role="alert"></div><div class="form-actions"><button class="btn" type="submit">اعمال مشخصات ${icon('check',16)}</button><button type="button" class="btn secondary" data-action="closeDialog">انصراف</button></div></form>`);}
function privacyDialog(){openDialog('حریم خصوصی شما',`<p>محاسبات در مرورگر شما انجام می‌شود. این برنامه دریافت غذایی، مشخصات مرجع و انتخاب داروها را به سرور ارسال نمی‌کند. زیرساخت میزبانی ممکن است اطلاعات فنی معمول درخواست، مانند IP، را ثبت کند.</p><p>ذخیره جلسه اختیاری است و از حافظه محلی مرورگر استفاده می‌کند؛ رمزنگاری بالینی و دسترسی چندکاربره ندارد. فایل خروجی نیز حاوی مشخصات و دریافت‌های ثبت‌شده است؛ آن را در محل امن نگه دارید.</p><p>برای نگهداری یا پاک‌کردن اطلاعات به فضای کار بروید. استفاده از پیوندهای منابع، شما را به وب‌سایت دیگری هدایت می‌کند.</p><div class="form-actions"><a class="btn" href="#workspace" data-action="closeDialog">مدیریت داده‌ها</a><button class="btn secondary" data-action="closeDialog">متوجه شدم</button></div>`);}
const routes={home:'نمای کلی',vitamins:'دانشنامه ویتامین‌ها',vitamin:'پرونده ویتامین',calculator:'محاسبه دریافت روزانه',compare:'مقایسه ویتامین‌ها',safety:'ایمنی و تداخلات',evidence:'منابع و شواهد علمی',workspace:'فضای کار تخصصی',about:'درباره من'};
let currentRoute='home';
function render({focus=false}={}){const parts=location.hash.slice(1).split('/'),route=parts[0]||'home',id=parts[1];currentRoute=route;if(route==='calculator'&&vitaminById[id])state.selected=id;const html=route==='home'?home():route==='vitamins'?vitaminList():route==='vitamin'?vitaminDetail(id):route==='calculator'?calculator():route==='compare'?compare():route==='safety'?safety():route==='evidence'?evidence():route==='workspace'?workspace():route==='about'?about():notFound();$('#main').innerHTML=html;$('#breadcrumb').innerHTML=`خانه <b>/</b> ${routes[route]||'صفحه ناموجود'}`;document.title=`${routes[route]||'صفحه ناموجود'} | ویتارا`;document.querySelectorAll('[data-route]').forEach(a=>{const active=a.dataset.route===(route==='vitamin'?'vitamins':route);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(route==='vitamins')updateVitaminResults();if(route==='calculator')updateCalc();if(route==='safety')safetyResults();closeMenu();if(focus){$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
function closeMenu(){$('#sidebar').classList.remove('open');$('#scrim').classList.remove('visible');$('#menuToggle').setAttribute('aria-expanded','false');}
$('#menuToggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#scrim').classList.toggle('visible',open);$('#menuToggle').setAttribute('aria-expanded',String(open));});$('#scrim').addEventListener('click',closeMenu);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
document.addEventListener('input',e=>{if(e.target.id==='vitaminSearch'){state.query=e.target.value;updateVitaminResults();}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='vitaminSelect'){state.selected=el.value;state.entryTab='food';location.hash='calculator/'+el.value;}if(el.dataset.compare){const next=state.compare.includes(el.dataset.compare)?state.compare.filter(x=>x!==el.dataset.compare):[...state.compare,el.dataset.compare];if(next.length<2||next.length>4){el.checked=!el.checked;toast('برای مقایسه، بین دو تا چهار ویتامین انتخاب کنید.');return;}state.compare=next;render();}if(el.dataset.drug){state.drugs=el.checked?[...state.drugs,el.dataset.drug]:state.drugs.filter(x=>x!==el.dataset.drug);safetyResults();}if(el.dataset.risk){state.risk=el.checked?[...state.risk,el.dataset.risk]:state.risk.filter(x=>x!==el.dataset.risk);safetyResults();}if(el.id==='persistToggle'){state.persist=el.checked;if(state.persist){save();toast(state.persist?'ذخیره اختیاری این مرورگر فعال شد.':'ذخیره ممکن نشد.');}else{try{localStorage.removeItem(storageKey);}catch{}toast('ذخیره خودکار خاموش شد؛ جلسه فعلی تا بازخوانی صفحه باقی می‌ماند.');}}if(el.id==='entryKind'&&state.selected==='B9'){$('#amountLabel').textContent=el.value==='food'?'مقدار فولات طبیعی غذا (mcg DFE)':'مقدار اسیدفولیک (mcg، همراه غذا)';$('#manualUnit').options[0].value=el.value==='food'?'mcg DFE':'mcg folic acid';$('#manualUnit').options[0].textContent=el.value==='food'?'mcg DFE':'mcg اسیدفولیک (تبدیل به DFE)';$('#folateNote').textContent=el.value==='food'?'فقط فولات طبیعی غذا را به واحد mcg DFE وارد کنید.':'اسیدفولیک همراه غذا را وارد کنید؛ DFE برچسب یا متیل‌فولات در این حالت پذیرفته نمی‌شود.';}});
document.addEventListener('submit',e=>{const form=e.target;if(!['profileForm','dialogProfile','foodForm','manualForm'].includes(form.id))return;e.preventDefault();const f=new FormData(form);try{if(form.id==='profileForm'||form.id==='dialogProfile'){const p={age:parseNumber(f.get('age')),sex:f.get('sex'),stage:f.get('stage'),smoker:f.has('smoker')};validateProfile(p);state.profile=p;save();if(form.id==='dialogProfile')$('#dialog').close();render();toast('مشخصات مرجع اعمال شد.');}else{if(state.entries.length>=1000)throw new Error('ظرفیت این جلسه تکمیل است؛ پشتیبان بگیرید و داده‌ها را پاک کنید.');const entry=form.id==='foodForm'?foodEntry(state.selected,f.get('food'),f.get('servings')):manualEntry(state.selected,Object.fromEntries(f));state.entries.push(entry);save();updateCalc();$('#entryError').textContent='';toast('دریافت به گزارش امروز اضافه شد.');}}catch(err){const target=form.id==='profileForm'?'#profileError':form.id==='dialogProfile'?'#dialogError':'#entryError';$(target).textContent=err.message;}});
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(!btn)return;const a=btn.dataset.action,id=btn.dataset.id;if(a==='skipContent'){e.preventDefault();$('#main').focus();}if(a==='favorite'){state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();btn.classList.toggle('saved',state.favorites.includes(id));btn.setAttribute('aria-pressed',String(state.favorites.includes(id)));if(currentRoute==='vitamins'&&state.filter==='saved')updateVitaminResults();}if(a==='filter'){state.filter=id;document.querySelectorAll('[data-action="filter"]').forEach(b=>{b.classList.toggle('active',b.dataset.id===id);b.setAttribute('aria-pressed',String(b.dataset.id===id));});updateVitaminResults();}if(a==='entryTab'){state.entryTab=id;$('#entryFormContainer').innerHTML=entryForm();}if(a==='removeEntry'){state.entries=state.entries.filter(x=>x.id!==id);save();updateCalc();}if(a==='clearVitamin'){state.entries=state.entries.filter(x=>x.vitamin!==state.selected);save();updateCalc();toast('دریافت‌های این ویتامین پاک شد.');}if(a==='profile')profileDialog();if(a==='privacy')privacyDialog();if(a==='closeDialog')$('#dialog').close();if(a==='print')window.print();if(a==='export'){const blob=new Blob([JSON.stringify(snapshot(),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download='vitara-report-'+new Date().toISOString().slice(0,10)+'.json';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('فایل پشتیبان آماده دریافت شد.');}if(a==='import'){$('#importFile').value='';$('#importFile').click();}if(a==='erase')openDialog('پاک‌کردن همه داده‌ها',`<p>دریافت‌ها، مشخصات، نشان‌شده‌ها و داده ذخیره‌شده این برنامه پاک می‌شوند. اگر لازم است، ابتدا پشتیبان بگیرید.</p><div class="form-actions"><button class="btn danger" data-action="confirmErase">پاک‌کردن همه</button><button class="btn secondary" data-action="closeDialog">انصراف</button></div>`);if(a==='confirmErase'){state.entries=[];state.favorites=[];state.drugs=[];state.risk=[];state.profile={age:30,sex:'female',stage:'ordinary',smoker:false};state.persist=false;try{localStorage.removeItem(storageKey);}catch{}$('#dialog').close();render();toast('همه داده‌های برنامه در این مرورگر پاک شد.');}if(a==='confirmImport'){state.profile=pendingImport.profile;state.entries=pendingImport.entries;pendingImport=null;save();$('#dialog').close();render();toast('پشتیبان بازیابی شد؛ مقادیر واردشده را بررسی کنید.');}});
let pendingImport=null;$('#importFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1_000_000)throw new Error('حجم فایل پشتیبان باید کمتر از یک مگابایت باشد.');pendingImport=safeSnapshot(JSON.parse(await file.text()));openDialog('بازیابی پشتیبان',`<p>${fmt(pendingImport.entries.length)} ردیف دریافت و مشخصات مرجع از فایل خوانده شد. بازیابی، داده‌های جلسه فعلی را جایگزین می‌کند. مقادیر فایل، ورودی کاربر هستند و باید بررسی شوند.</p><div class="form-actions"><button class="btn" data-action="confirmImport">جایگزینی و بازیابی</button><button class="btn secondary" data-action="closeDialog">انصراف</button></div>`);}catch(err){toast('بازیابی انجام نشد: '+err.message);}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close();});
window.addEventListener('hashchange',()=>{if($('#dialog').open)$('#dialog').close();render({focus:true});});render();
